@spec generators_spec  src=tests/specs/generators_spec.lua  loc=967  cases=69
@exercises generators (generators)
@surface   generators.glyphOf, generators.labelOf, generators.fieldsFor, generators.parksNotes, generators.parkWindows, generators.continuousTargets, generators.chainDestType, generators.destOf, generators.retarget, generators.fieldRange, generators.waveBody, generators.customise, generators.seed, generators.thinCurve

# Intent
  generators.lua: slide glide-in envelope.

# Helpers
  @fn expand(kind, hostRec, params, ctx)  @ 8-10
      -- Kinds run alone here, so the chain state equals the original: stream == host (the chain head).
  @fn slideCtx(nextNote, pbRangeCents)  @ 14-17
      -- A note host: its own note on a lane, and a ctx resolving the successor past the window end.
      -- An `endppq` short of that onset is the gap that gates the glide.
  @fn noteHost(endppq)  @ 18-21
  @fn regionHost(notes)  @ 23-25
      -- A region owns no lane of its own; its members carry theirs.
  @fn member(ppq, endppq, pitch, lane)  @ 26-28
  @fn abutting()  @ 30-32
      -- Three lane-1 members abutting across the region: 60 -> 62 -> 64, a whole tone apiece.
  @fn withP(overrides)  @ 34
  @fn curve(delta)  @ 36-40
      -- A delta read positionally as {ppq, val, shape} -- how a glide reads whole.
  @fn triangle()  @ 43-49
      -- A loop-closed triangle in the normalized domain (-1 .. +1 .. -1), one QN long.
  @fn pts(rows)  @ 53-59
      -- Curve points positionally: {ppq, val, shape?, tension?}; shape defaults to linear, the one kind
      -- thinCurve is allowed to drop.

# Cases
  @case 'every registered kind carries a glyph, one codepoint, shared with no other kind'  [pure]  @ 66-75
  @case 'glyphOf resolves off the registry, and falls back for a kind the registry has lost'  [pure]  @ 79-83
  @case 'labelOf resolves off the registry, and keeps a lost kind\'s name in the mark'  [pure]  @ 87-92
  @case 'fieldsFor gives a lost kind no rows'  [pure]  @ 96-100
  @case 'a note host glides away: its anchor is the window end, so in has nowhere to depart from'  [pure]  @ 106-113
  @case 'a gap gates the glide: a note's tail must reach its successor's onset'  [pure]  @ 117-121
  @case 'an overrunning tail still abuts (a note host's endppq is its unclipped authored ceiling)'  [pure]  @ 125-130
  @case 'slide interval includes detune (the microtonal offset rides in detune, not pitch)'  [pure]  @ 134-138
  @case 'slide clamps the target to ctx.pbRangeCents (a pb can only bend so far)'  [pure]  @ 142-146
  @case 'no successor, or a unison one, yields no delta (the channel is left untouched)'  [pure]  @ 150-155
  @case 'a region glides in at each abutting pair: depart on the onset, arrive a glide later'  [pure]  @ 159-166
  @case 'a region glides away when asked: arrive a tick before the onset, re-centre on it'  [pure]  @ 170-177
  @case 'a region never glides out of itself -- its last member has no successor to reach'  [pure]  @ 181-186
  @case 'a gap inside a region gates that pair alone'  [pure]  @ 190-197
  @case 'a region glides its lane-1 voice; a chord's upper lanes are not the monophonic line'  [pure]  @ 201-211
  @case 'a derived note carries no lane yet, so it counts as the monophonic line'  [pure]  @ 215-222
  @case 'per=octave reads the same fraction as a rate: one octave takes `over`'  [pure]  @ 226-234
  @case 'the glide shape rides the breakpoint the glide opens on (a shape governs its right)'  [pure]  @ 238-243
  @case 'consecutive glides meeting on one tick fold into one breakpoint (two cannot share a ppq)'  [pure]  @ 247-255
  @case 'trill tiles the window from its start, alternating host pitch with the cents demand'  [pure]  @ 261-274
  @case 'trill measures its demand from what the host sounds, detune and all'  [pure]  @ 278-286
  @case 'a trill\'s tiles each name a step of their own -- the host\'s, and the demand above it'  [pure]  @ 290-302
  @case 'a trill off a host with no intent derives none -- the field stays sparse'  [pure]  @ 306-313
  @case 'parksNotes is true for any note-dest kind, false for a continuous kind / husk'  [pure]  @ 319-324
  @case 'parkWindows emits an evType-tagged window per continuous/replace target (note discrete, cc, pb augment)'  [pure]  @ 328-343
  @case 'the ownership predicates ignore bypass: a bypassed chain still parks and still scopes its target'  [pure]  @ 347-357
  @case 'chainDestType demotes a bypassed replace stage to augment, and only that stage'  [pure]  @ 361-371
  @case 'destOf falls back to the registry dest; a dest param overrides it'  [pure]  @ 377-382
  @case 'fieldsFor prepends a Dest row only where the kind can serve more than one target'  [pure]  @ 386-394
  @case 'retarget between dests of equal reference leaves the magnitudes alone'  [pure]  @ 398-403
  @case 'retarget rescales magnitudes by proportion of the dest reference'  [pure]  @ 407-413
  @case 'fieldRange spans both ways for a signed magnitude, one way for an unsigned one'  [pure]  @ 417-423
  @case 'retarget carries a signed magnitude across with its sign intact'  [pure]  @ 427-433
  @case 'parkWindows follows the dest param, not the registry (a retargeted pb kind parks cc)'  [pure]  @ 437-444
  @case 'a sine-wave lfo on a cc dest tiles the window with extrema in cc steps, 0 at both ends'  [pure]  @ 450-464
  @case 'velPattern cycles its percent pattern per distinct onset; a chord shares one step'  [pure]  @ 470-485
  @case 'velPattern walks onset order regardless of input order, clamping vel to 1..127'  [pure]  @ 489-499
  @case 'ostinato tracks the sounding pitch across the region, not just the first note'  [pure]  @ 505-517
  @case 'ostinato rests when no region note sounds at the gate onset'  [pure]  @ 521-530
  @case 'ostinato emits one gated note per sounding voice (a chord -> multiple lanes)'  [pure]  @ 534-545
  @case 'chord-stamp rebases the pattern chord onto each member; lane-1 note lands on the trigger'  [pure]  @ 551-568
  @case 'chord-stamp moves every voice by the cents from its root to the trigger'  [pure]  @ 572-592
  @case 'chord-stamp fires a chord on every region member (all lanes are triggers)'  [pure]  @ 596-612
  @case 'chord-stamp with no lane-1 note in the pattern is inert (no root to rebase from)'  [pure]  @ 616-626
  @case 'chord-stamp voices name the trigger\'s step plus their own interval from the root'  [pure]  @ 630-645
  @case 'the kinds that copy a pitch copy the intent standing beside it'  [pure]  @ 651-663
  @case 'lfo tiles the curve at 1/period QN, mapping each val by offset + scale, edges seeded'  [pure]  @ 669-686
  @case 'lfo maps norm in whatever units the dest counts in -- cents on pb'  [pure]  @ 690-699
  @case 'lfo does not clamp -- the body holds no dest knowledge, and the cc seat clamps'  [pure]  @ 703-712
  @case 'lfo with an empty or lengthless curve is inert (no delta)'  [pure]  @ 716-725
  @case 'every wave draws a loop-closed normalized body, and all but square open at rest'  [pure]  @ 731-745
  @case 'the sine wave is four slow-bridged extrema; the triangle is the same points ridden linearly'  [pure]  @ 749-762
  @case 'a saw resets mid-body, so its cycle starts and ends at rest'  [pure]  @ 766-778
  @case 'a wave body is four beats of the take that asked for it, never a fixed tick count'  [pure]  @ 782-790
  @case 'a cycle squeezed below the tick still emits its breakpoints a tick apart'  [pure]  @ 794-807
  @case 'a named wave is what the lfo expands -- a stored body is dormant until custom'  [pure]  @ 811-823
  @case 'onset ramps the whole displacement in from rest over its QN, offset included'  [pure]  @ 827-839
  @case 'customise stamps the wave onto the body and flips the stage to custom'  [pure]  @ 843-856
  @case 'custom is an arrival: the wave ladder steps over it, and its own pick re-seeds'  [pure]  @ 860-872
  @case 'thinCurve returns a degenerate curve verbatim -- endpoints are never candidates'  [pure]  @ 878-885
  @case 'thinCurve collapses a collinear linear run to its endpoints'  [pure]  @ 889-896
  @case 'thinCurve drops a spike whose vertical error only meets the tolerance'  [pure]  @ 900-904
  @case 'thinCurve keeps a spike whose vertical error exceeds the tolerance'  [pure]  @ 908-911
  @case 'thinCurve keeps a stepped run whole, collinear though its points are'  [pure]  @ 915-919
  @case 'thinCurve rides a curved point through with its tension intact'  [pure]  @ 923-929
  @case 'thinCurve lets a non-linear point pin its successor as well as itself'  [pure]  @ 933-938
  @case 'thinCurve treats a missing shape as non-linear -- under-thin over silently ramping'  [pure]  @ 942-946
  @case 'thinCurve keeps a stack of coincident points -- a zero-width span has no chord'  [pure]  @ 950-954
  @case 'thinCurve gives a dual-point pair no special protection'  [pure]  @ 958-964

